@tool
def calculate_expense(amount: float, category: str, description: str) -> str:
    """
    Log an expense with an amount, category and description.
    Parameters:
        amount      - Amount in PKR (float)
        category    - One of: food, transport, entertainment, shopping, health, utilities, other
        description - Short description of what was purchased
    """
    date = datetime.now().strftime("%Y-%m-%d %H:%M")
    cat = category.lower().strip()
    
    # Fallback to 'other' if category is invalid
    if cat not in st.session_state.monthly_budget and cat != "other":
        cat = "other"

    entry = {
        "id": len(st.session_state.expenses) + 1,
        "amount": amount,
        "category": cat,
        "description": description,
        "date": date,
    }
    st.session_state.expenses.append(entry)

    if cat in st.session_state.monthly_spending:
        st.session_state.monthly_spending[cat] += amount

    return (
        f"Expense logged successfully!\n"
        f"Date: {date}\n"
        f"Amount: PKR {amount:,.2f}\n"
        f"Category: {cat.title()}\n"
        f"Description: {description}"
    )


@tool
def get_budget_status(category: str) -> str:
    """
    Check the remaining monthly budget for a specific spending category.
    Parameters:
        category - One of: food, transport, entertainment, shopping, health, utilities
    """
    cat = category.lower().strip()
    budgets  = st.session_state.monthly_budget
    spending = st.session_state.monthly_spending

    if cat not in budgets:
        return f"Category '{cat}' not found. Available: {', '.join(budgets.keys())}"

    budget    = budgets[cat]
    spent     = spending.get(cat, 0)
    remaining = budget - spent
    pct       = (spent / budget * 100) if budget else 0
    status    = "Over budget!" if remaining < 0 else ("Warning!" if pct > 75 else "On track")

    return (
        f"Budget Status - {cat.title()}\n"
        f"Monthly Budget:   PKR {budget:,.0f}\n"
        f"Amount Spent:     PKR {spent:,.0f}\n"
        f"Remaining:        PKR {remaining:,.0f}\n"
        f"Usage:            {pct:.1f}%\n"
        f"Status:           {status}"
    )


@tool
def convert_currency(amount: float, from_currency: str, to_currency: str) -> str:
    """
    Convert between currencies using fixed rates.
    Supported currencies: USD, PKR, EUR, GBP, AED, SAR, CAD, AUD
    """
    rates = {
        "USD": 1.0, "PKR": 280.5, "EUR": 0.92, "GBP": 0.79,
        "AED": 3.67, "SAR": 3.75, "CAD": 1.36, "AUD": 1.53,
    }
    src = from_currency.upper().strip()
    tgt = to_currency.upper().strip()

    if src not in rates or tgt not in rates:
        return f"Unsupported currency mapping. Supported: {', '.join(rates.keys())}"

    usd_amount = amount / rates[src]
    converted  = usd_amount * rates[tgt]

    return (
        f"Currency Conversion\n"
        f"{amount:,.2f} {src} = {converted:,.2f} {tgt}"
    )


@tool
def calculate_savings_goal(target_amount: float, monthly_savings: float) -> str:
    """
    Calculate how long to reach a savings target.
    Parameters:
        target_amount   - Target savings amount in PKR
        monthly_savings - Monthly amount being saved in PKR
    """
    if monthly_savings <= 0:
        return "Monthly savings must be greater than zero."

    current_savings = st.session_state.savings_current
    remaining = target_amount - current_savings
    
    if remaining <= 0:
        return f"Congratulations! You have already reached your goal of PKR {target_amount:,.0f}!"

    months_needed = math.ceil(remaining / monthly_savings)
    years  = months_needed // 12
    months = months_needed % 12
    target_date = (datetime.now() + timedelta(days=30 * months_needed)).strftime("%B %Y")
    
    return (
        f"Savings Goal Analysis\n"
        f"Target Amount:        PKR {target_amount:,.0f}\n"
        f"Current Savings:      PKR {current_savings:,.0f}\n"
        f"Monthly Savings:      PKR {monthly_savings:,.0f}\n"
        f"Time Required:        {years}y {months}m ({months_needed} months)\n"
        f"Estimated Reach:      {target_date}"
    )


@tool
def get_spending_tip(category: str) -> str:
    """
    Return a money-saving tip for a spending category.
    Parameters:
        category - The category where user overspends (e.g., food, transport, entertainment)
    """
    tips_db = {
        "food": [
            "Cook at home 4-5 days a week to cut food expenses by up to 40%.",
            "Shop with a list to avoid impulse buying at the grocery store.",
            "Buy non-perishable staples in bulk to save money long-term."
        ],
        "transport": [
            "Carpool or use public transit twice a week to save on fuel.",
            "Keep your tires properly inflated to improve gas mileage.",
            "Bundle errands into one trip to save fuel and time."
        ],
        "entertainment": [
            "Cancel unused subscriptions — they quietly drain your budget.",
            "Look for free community events and parks on weekends.",
            "Host potluck dinners instead of going out to expensive restaurants."
        ],
        "shopping": [
            "Apply the 24-hour rule before making any non-essential purchase.",
            "Compare prices online before buying clothes or electronics.",
            "Buy high-quality classic items rather than cheap fast fashion."
        ]
    }

    cat_clean = category.lower().strip()
    tips = tips_db.get(cat_clean, [
        "Track every expense for 30 days to understand your spending patterns.",
        "Set up automatic transfers to a savings account on payday.",
        "Build a 3-6 month emergency fund before focusing on investments."
    ])
    
    selected = random.choice(tips)
    return f"💡 Money-Saving Tip for {category.title()}:\n{selected}"


