@tool
def get_all_budget_summary() -> str:
    """Get a summary of ALL budget categories at once."""
    budgets  = st.session_state.monthly_budget
    spending = st.session_state.monthly_spending
    lines = ["Monthly Budget Overview\n"]
    for cat in budgets:
        b, s = budgets[cat], spending.get(cat, 0)
        p = s / b * 100 if b else 0
        lines.append(f"{cat.title()}: Budget PKR {b:,.0f} | Spent PKR {s:,.0f} | {p:.0f}% used")
    return "\n".join(lines)


@tool
def calculate_loan_emi(principal: float, annual_rate: float, tenure_months: int) -> str:
    """Calculate monthly EMI (Equated Monthly Instalment) for a loan."""
    if annual_rate <= 0 or tenure_months <= 0:
        return "Interest rate and tenure must be positive numbers."
    r = (annual_rate / 100) / 12
    emi = principal * r * (1 + r)**tenure_months / ((1 + r)**tenure_months - 1)
    return f"Loan EMI for PKR {principal:,.0f} at {annual_rate}% for {tenure_months} months is PKR {emi:,.2f}/month."


