def fmt_pkr(amount):
    return f"PKR {amount:,.0f}"

def spend_pct(cat):
    b = st.session_state.monthly_budget.get(cat, 1)
    s = st.session_state.monthly_spending.get(cat, 0)
    return min(s / b * 100, 100)

def savings_pct():
    g = st.session_state.savings_goal
    c = st.session_state.savings_current
    return min(c / g * 100, 100) if g else 0


