def make_budget_donut():
    spending = st.session_state.monthly_spending
    cats   = list(spending.keys())
    vals   = list(spending.values())
    colors = [CAT_COLORS.get(c, "#8b5cf6") for c in cats]

    fig = go.Figure(go.Pie(
        labels=[c.title() for c in cats],
        values=vals,
        hole=0.62,
        marker=dict(colors=colors, line=dict(color="#0d0d1f", width=2)),
        textinfo="none",
        hovertemplate="<b>%{label}</b><br>PKR %{value:,.0f}<br>%{percent}<extra></extra>",
    ))
    fig.update_layout(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        showlegend=True,
        legend=dict(font=dict(color="rgba(255,255,255,0.7)", size=11), bgcolor="rgba(0,0,0,0)"),
        margin=dict(t=10, b=10, l=10, r=10),
        height=240,
        annotations=[dict(
            text=f"<b>PKR {sum(vals):,.0f}</b><br><span style='font-size:10px'>Total Spent</span>",
            x=0.5, y=0.5,
            font=dict(size=13, color="white"),
            showarrow=False,
        )],
    )
    return fig


def make_budget_bars():
    budgets  = st.session_state.monthly_budget
    spending = st.session_state.monthly_spending
    cats   = list(budgets.keys())
    colors = [CAT_COLORS.get(c, "#8b5cf6") for c in cats]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        x=[c.title() for c in cats],
        y=[budgets[c] for c in cats],
        name="Budget",
        marker=dict(color="rgba(255,255,255,0.06)"),
        hovertemplate="%{x}<br>Budget: PKR %{y:,.0f}<extra></extra>",
    ))
    fig.add_trace(go.Bar(
        x=[c.title() for c in cats],
        y=[spending.get(c, 0) for c in cats],
        name="Spent",
        marker=dict(color=colors, opacity=0.85),
        hovertemplate="%{x}<br>Spent: PKR %{y:,.0f}<extra></extra>",
    ))
    fig.update_layout(
        barmode="overlay",
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="rgba(255,255,255,0.7)", size=11),
        legend=dict(bgcolor="rgba(0,0,0,0)", font=dict(color="rgba(255,255,255,0.6)")),
        xaxis=dict(showgrid=False),
        yaxis=dict(showgrid=True, gridcolor="rgba(255,255,255,0.04)"),
        margin=dict(t=10, b=10, l=10, r=10),
        height=240,
    )
    return fig


