        st.markdown('<div class="section-header"><div class="section-header-title">Categories</div><div class="section-header-line"></div></div>', unsafe_allow_html=True)

        for cat in st.session_state.monthly_budget:
            pct   = spend_pct(cat)
            color = CAT_COLORS.get(cat, "#8b5cf6")
            spent = st.session_state.monthly_spending.get(cat, 0)
            bgt   = st.session_state.monthly_budget[cat]
            bar_color = "#ef4444" if pct >= 100 else ("#f59e0b" if pct >= 75 else color)

            st.markdown(f"""
                <div style="margin-bottom:0.7rem;">
                    <div style="display:flex; justify-content:space-between; font-size:0.875rem; margin-bottom:0.25rem;">
                        <span style="color:var(--foreground); font-weight:500;">{cat.title()}</span>
                        <span style="color:var(--muted-foreground);">{pct:.0f}%</span>
                    </div>
                    <div style="height:6px; background:var(--muted); border-radius:999px; overflow:hidden;">
                        <div style="height:100%; width:{pct}%; background:{bar_color}; border-radius:999px;"></div>
                    </div>
                </div>
            """, unsafe_allow_html=True)
            
        return provider, api_key


