# ─────────────────────────────────────────────
# EXPENSE HISTORY TAB
# ─────────────────────────────────────────────

def render_expense_history():
    expenses = st.session_state.expenses
    if not expenses:
        st.markdown("""
            <div style="text-align:center; padding:2rem; color:var(--muted-foreground);">
                <div style="margin-top:0.5rem; font-size:0.9rem;">No expenses logged yet.</div>
            </div>
        """, unsafe_allow_html=True)
        return

    total = sum(e["amount"] for e in expenses)
    st.markdown(f"**{len(expenses)} Expense(s) This Session** — Total: **PKR {total:,.2f}**")

    for exp in reversed(expenses):
        color = CAT_COLORS.get(exp["category"], "#8b5cf6")
        st.markdown(f"""
            <div class="expense-row">
                <div class="expense-cat-dot" style="background:{color};"></div>
                <div style="flex:1;">
                    <div class="expense-name">{exp["description"]}</div>
                    <div class="expense-cat">{exp["category"].title()} · {exp["date"]}</div>
                </div>
                <div class="expense-amount" style="color:{color};">PKR {exp["amount"]:,.2f}</div>
            </div>
        """, unsafe_allow_html=True)


# ─────────────────────────────────────────────
# CHAT TAB
# ─────────────────────────────────────────────

def render_chat():
    chat_container = st.container(height=460, border=False)

    with chat_container:
        if not st.session_state.messages:
            st.markdown("""
                <div style="text-align:center; padding:2.5rem 1rem; color:var(--muted-foreground);">
                    <div style="font-size:0.9rem;">Start a conversation!</div>
                </div>
            """, unsafe_allow_html=True)

        for msg in st.session_state.messages:
            if msg["role"] == "user":
                st.markdown(f"""
                    <div class="chat-bubble-user">
                        <div>
                            <div class="bubble">{msg["content"]}</div>
                            <div class="chat-meta" style="text-align:right;">{msg.get("time","")}</div>
                        </div>
                    </div>
                """, unsafe_allow_html=True)
            else:
                content_html = msg["content"].replace("\n", "<br>")
                st.markdown(f"""
                    <div class="chat-bubble-ai">
                        <div>
                            <div class="bubble">{content_html}</div>
                            <div class="chat-meta">{msg.get("time","")}</div>
                        </div>
                    </div>
                """, unsafe_allow_html=True)


# ─────────────────────────────────────────────
# MAIN
# ─────────────────────────────────────────────

def main():
    provider, api_key = render_sidebar()

    agent_executor = None
    if api_key:
        try:
            agent_executor = build_agent(api_key, provider)
        except Exception as exc:
            st.error(f"Failed to initialize agent with {provider}: {exc}")

    render_hero()

    st.markdown("<br>", unsafe_allow_html=True)
    render_features()

    tab_chat, tab_charts, tab_history = st.tabs([
        "AI Chat Assistant",
        "Financial Dashboard",
        "Expense History",
    ])

    with tab_chat:
        render_chat()

    with tab_charts:
        render_charts()

    with tab_history:
        render_expense_history()

    user_input = st.chat_input("Ask FinanceAI anything about your finances...")
    
    if user_input:
        now_str = datetime.now().strftime("%I:%M %p")
        st.session_state.messages.append({"role": "user", "content": user_input, "time": now_str})

        if agent_executor:
            with st.spinner(f"FinanceAI is thinking..."):
                try:
                    result = agent_executor.invoke({'messages': [{'role': 'user', 'content': user_input}]})
                    response = result['messages'][-1].content
                except Exception as exc:
                    response = f"Error: {str(exc)}\n\nPlease check your API key and try again."
        else:
            response = "Please add your API key (AWS Bedrock or Google Gemini) in the sidebar to start chatting. You can get a free Google Gemini key from Google AI Studio."

        st.session_state.messages.append({"role": "assistant", "content": response, "time": now_str})
        st.rerun()

if __name__ == "__main__":
    main()
